struct Point {
  int x;
  int y;
};

typedef int MyInt;

struct Point global_point;
int global_array[4];

int compute(struct Point *point_ptr, int a, int b) {
  a += b;
  a -= 1;
  a *= 2;
  a /= 3;
  a %= 4;
  a &= 255;
  a |= 1;
  a ^= 2;
  a <<= 1;
  a >>= 1;
  b = (a > b) ? a : b;
  b = (a, b);
  point_ptr->x = a;
  (*point_ptr).y = b;
  global_array[0] = a;
  a++;
  a--;
  ++a;
  --a;
  b = *&a;
  b = (int)a;
  b = (MyInt)b;
  b = _Alignof(int);
  return a + b + point_ptr->x + global_array[0];
}

int main(void) {
  return compute(&global_point, 1, 2);
}

